            @CacheEvict(value = CacheConstants.CACHE_NAME_ACCOUNT_AUTH_INFO, key = "#accountId+''"),
            @CacheEvict(value = CacheConstants.CACHE_NAME_ACCOUNT_AUTH_PERMISSION, key = "#accountId+''"),
    })
    @Transactional(rollbackFor = Exception.class)
    public void updateAccountRole(Long accountId, List<String> roleCodes, String modifierName, String modifierAccountId){
        List<String> authAccountRoleDOS = authAccountRoleDOMapper.getRoleCodes(accountId);
        ObjectSets<String> sets = ObjectSets.newInstance(authAccountRoleDOS, roleCodes, new ObjectSets.Equal<String>() {
            @Override
            public boolean equals(String a, String b) {
                return a.equals(b);
            }

            @Override
            public List<String> objectTypeIdentityField() {
                return Collections.emptyList();
            }
        });
        if (CollectionUtils.isNotEmpty(sets.getDeleteObjects())) {
            for (String ruleCode : sets.getDeleteObjects()) {
                authAccountRoleDOMapper.deleteByRoleCodeAndAccountId(ruleCode, accountId);
            }
        }
        if (CollectionUtils.isNotEmpty(sets.getNewObjects())) {
            // 对于新增的，确保修改人账号有此角色
            checkRolesInAccount(modifierAccountId, sets.getNewObjects());

            for (String ruleCode : sets.getNewObjects()) {
                AuthAccountRoleDO authAccountRoleDO = new AuthAccountRoleDO();
                authAccountRoleDO.setAccountId(accountId);
                authAccountRoleDO.setRoleCode(ruleCode);
                authAccountRoleDO.setTenantCode("cathay");
                authAccountRoleDO.setIsValid(1);
                authAccountRoleDOMapper.insertSelective(authAccountRoleDO);
            }
        }

        // 更新账号更新人和时间
        AuthAccountDO existAccount = authAccountDOMapper.selectByAccountId(accountId);
        if (existAccount == null){
            throw new BizException("账号不存在:"+ accountId);
        }

        AuthAccountDO authAccountDO = new AuthAccountDO();
        authAccountDO.setId(existAccount.getId());
        authAccountDO.setModifierName(modifierName);
        int res = authAccountDOMapper.updateByPrimaryKeySelective(authAccountDO);
        if (res <= 0){
            throw new BizException("更新失败:"+ accountId);
        }
    }

private void checkRolesInAccount(String accountId, List<String> roleCodes) {
        AccountAuthE accountAuthE = this.getAccountAuthNoCache(accountId, false);
        for (String roleCode : roleCodes) {
            if (!accountAuthE.getAuthRoles().containsKey(roleCode)) {
                throw new BizException("账号无权分配此角色:"+roleCode);
            }
        }
    }

public AccountAuthE getAccountAuthNoCache(String accountId, boolean permission) {
        AccountAuthE accountAuthE = new AccountAuthE();
        accountAuthE.setAccountId(accountId);

        // 查询外呼账号
        String phoneCallAccount = getPhoneCallAccount(Integer.parseInt(accountId));

        AccountE accountE = authConverter.toAccountE(authAccountDOMapper.selectByAccountId(Long.parseLong(accountId)), phoneCallAccount);
        accountAuthE.setAccountE(accountE);

        List<String> roleCodes = authAccountRoleDOMapper.getRoleCodes(Long.parseLong(accountId));
        if (CollectionUtils.isNotEmpty(roleCodes)) {
            List<AuthRoleDO> authRoleDOS = authRoleDOMapper.selectByRoleCodes(roleCodes);
            Map<String, AuthRoleE> authRoles = Maps.newHashMap();
            for (AuthRoleDO authRoleDO : authRoleDOS) {
                authRoles.put(authRoleDO.getRoleCode(), buildAuthRoleE(authRoleDO, permission));
            }
            accountAuthE.setAuthRoles(authRoles);
        }
        return accountAuthE;
    }

private AuthRoleE buildAuthRoleE(AuthRoleDO authRoleDO, boolean permission) {
        AuthRoleE authRoleE = new AuthRoleE();
        authRoleE.setRoleCode(authRoleDO.getRoleCode());
        authRoleE.setRoleArea(authRoleDO.getRoleArea());
        authRoleE.setRoleStatus(Byte.toString(authRoleDO.getRoleStatus()));
        authRoleE.setRoleName(authRoleDO.getRoleName());

        if (permission){
            List<String> permissionCodes = authRolePermissionDOMapper.getPermissionCodesByRole(authRoleDO.getRoleCode());
            List<AuthPermissionDO> authPermissionDOS = authPermissionDOMapper.selectList(permissionCodes);
            if (CollectionUtils.isNotEmpty(authPermissionDOS)) {
                List<AuthPermissionE> authPermissionES = new ArrayList<>();
                //遍历，转换
                authPermissionDOS.stream().forEach(authPermissionDO -> {
                    AuthPermissionE authPermissionE = authConverter.toAuthPermission(authPermissionDO);
                    authPermissionES.add(authPermissionE);
                });
                //正序排列
                Collections.sort(authPermissionES, Comparator.comparingInt(AuthPermissionE::getOrderNo));
                authRoleE.setPermissions(authPermissionES);
            }
        }
        return authRoleE;
    }

public String getPhoneCallAccount(Integer accountId) {
        PhoneCallAccountPoolDO phoneCallAccountPoolDO = phoneCallAccountPoolDOMapper.selectByBindAccount(accountId);
        if (phoneCallAccountPoolDO == null) {
            return null;
        }
        return phoneCallAccountPoolDO.getPhoneCallAccount();
    }

