public static <T> ObjectSets<T> newInstance(List<T> last, List<T> now, Equal<T> equal, Equal<T> valueEqual) {
        ObjectSets<T> t = new ObjectSets<>();
        t.equal = equal;
        t.valueEqual = valueEqual;
        t.lastSet(last);
